  j constant jsonb := $j$[
{"id":"e60b201d-8f63-4972-9b77-5085a85af855","recipe_group_id":"b6867e1c-874c-4f59-89d2-88de2fe8dc39","language":"es","slug":"pollo-a-la-naranja","public_path":"/pollo-a-la-naranja","source_url":null,"title":"Pollo a la naranja","excerpt":"Pollo a la naranja en sartén, con muslos dorados y una salsa de jugo de naranja, miel y tomillo. Para 4 personas, listo en 55 minutos.","summary":"El pollo a la naranja se hace con muslos de pollo con piel dorados en sartén y cocidos en una salsa de jugo de naranja, ralladura, miel, ajo y tomillo. Se doran primero para que la piel quede crujiente y después se cuecen tapados, a fuego bajo.\n\nSe cuece 15 minutos tapado y 10 minutos más sin tapar, hasta que la salsa espese y cubra el pollo. Se sirve con rodajas de naranja. Rinde 4 porciones.","category":"Platos principales","difficulty":"Fácil","course":"Plato principal","cuisine":"Mediterránea","prep_time_minutes":15,"cook_time_minutes":40,"total_time_minutes":55,"servings":4,"keywords":["pollo a la naranja","receta de pollo a la naranja","cómo hacer pollo a la naranja","muslos de pollo a la naranja","pollo con salsa de naranja","pollo en sartén","pollo con miel y naranja"],"ingredients":[{"name":"muslos de pollo con piel","amount":"1","unit":"kg","group":"Para el pollo"},{"name":"sal","amount":"1","unit":"cucharadita","group":"Para el pollo"},{"name":"pimienta negra molida","amount":"0.5","unit":"cucharadita","group":"Para el pollo"},{"name":"aceite de oliva","amount":"30","unit":"ml","group":"Para el pollo"},{"name":"dientes de ajo","amount":"3","unit":"","group":"Para el pollo"},{"name":"jugo de naranja recién exprimido (unas 3 naranjas)","amount":"250","unit":"ml","group":"Para la salsa"},{"name":"ralladura de naranja","amount":"1","unit":"cucharada","group":"Para la salsa"},{"name":"miel","amount":"1","unit":"cucharada","group":"Para la salsa"},{"name":"tomillo fresco","amount":"4","unit":"ramita","group":"Para la salsa"},{"name":"naranja en rodajas, para servir","amount":"1","unit":"","group":"Para servir"}],"steps":[{"title":"Prepara los ingredientes","content":"Seca 1 kg de muslos de pollo con papel de cocina y sazónalos con 1 cucharadita de sal y ½ de pimienta. Lava bien las naranjas, ralla 1 cucharada de piel, exprime 3 naranjas hasta tener 250 ml de jugo, pica 3 dientes de ajo y corta 1 naranja en rodajas.","image_url":"/recetas/pollo-a-la-naranja/paso-01.webp","image_alt":"Pollo a la naranja: Prepara los ingredientes"},{"title":"Dora los muslos","content":"Calienta 30 ml de aceite en una sartén ancha a fuego medio-alto. Dora los muslos con la piel hacia abajo 6 minutos, dales la vuelta y dóralos 4 minutos más. Hazlo en tandas si no caben.","image_url":"/recetas/pollo-a-la-naranja/paso-02.webp","image_alt":"Pollo a la naranja: Dora los muslos"},{"title":"Añade el ajo","content":"Baja el fuego a medio, retira el exceso de grasa y deja 1 cucharada en la sartén. Añade el ajo picado y sofríelo 1 minuto sin que se queme.","image_url":"/recetas/pollo-a-la-naranja/paso-03.webp","image_alt":"Pollo a la naranja: Añade el ajo"},{"title":"Vierte el jugo, la miel y el tomillo","content":"Añade 250 ml de jugo de naranja, 1 cucharada de ralladura, 1 cucharada de miel y 4 ramitas de tomillo. Lleva a ebullición y raspa el fondo de la sartén con una cuchara.","image_url":"/recetas/pollo-a-la-naranja/paso-04.webp","image_alt":"Pollo a la naranja: Vierte el jugo, la miel y el tomillo"},{"title":"Tapa y cuece","content":"Tapa la sartén, baja el fuego y cuece 15 minutos.","image_url":"/recetas/pollo-a-la-naranja/paso-05.webp","image_alt":"Pollo a la naranja: Tapa y cuece"},{"title":"Destapa y baña los muslos","content":"Destapa, da la vuelta a los muslos con unas pinzas y báñalos con la salsa. Cuece 5 minutos más sin tapar.","image_url":"/recetas/pollo-a-la-naranja/paso-06.webp","image_alt":"Pollo a la naranja: Destapa y baña los muslos"},{"title":"Reduce la salsa","content":"Sube un poco el fuego y reduce la salsa 5 minutos, hasta que espese y cubra los muslos. El pollo debe llegar a 75 °C en el centro.","image_url":"/recetas/pollo-a-la-naranja/paso-07.webp","image_alt":"Pollo a la naranja: Reduce la salsa"},{"title":"Sirve","content":"Pasa los muslos a una fuente, báñalos con la salsa y sirve con las rodajas de naranja y unas hojas de tomillo.","image_url":"/recetas/pollo-a-la-naranja/paso-08.webp","image_alt":"Pollo a la naranja: Sirve"}],"image_url":"/recetas/pollo-a-la-naranja/portada.webp","gallery":[{"url":"/recetas/pollo-a-la-naranja/portada.webp","alt":"Pollo a la naranja"}],"notes":"Seca bien el pollo para que la piel dore. Si usas muslos con hueso, necesitan unos 10 minutos más de cocción. La salsa queda más ligera si retiras la grasa sobrante antes de añadir el jugo. Si la naranja es muy dulce, añade unas gotas de limón al final. Se conserva tapado en la nevera hasta 3 días y se recalienta a fuego bajo.","nutrition":{"calories":662,"protein_g":41.9,"carbs_g":12,"fat_g":48.5,"sodium_mg":591,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 1000 g de muslos de pollo crudos con piel, 258 g de jugo de naranja (250 ml), 21 g de miel, 27,5 g de aceite de oliva, 9 g de ajo y 4 g de sal. La pimienta, el tomillo, la ralladura y las rodajas de naranja no se cuentan.","note":"Estimación por porción. Se cuenta toda la grasa y toda la sal, aunque parte de la grasa queda en la sartén, por lo que el valor es aproximado y algo alto. Con muslos con hueso, la porción comestible es menor.","inputs":[{"fdc_id":"172385","description":"Chicken, broilers or fryers, thigh, meat and skin, raw (1 kg de muslos con piel)","grams":1000,"per100":{"calories":221,"protein_g":16.5,"carbs_g":0.25,"fat_g":16.6,"saturated_fat_g":4.52,"fiber_g":0,"sodium_mg":81}},{"fdc_id":"169098","description":"Orange juice, raw (250 ml ≈ 258 g)","grams":258,"per100":{"calories":45,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sodium_mg":1}},{"fdc_id":"169640","description":"Honey (1 cucharada ≈ 21 g)","grams":21,"per100":{"calories":304,"protein_g":0.3,"carbs_g":82.4,"fat_g":0,"saturated_fat_g":0,"fiber_g":0.2,"sodium_mg":4}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (30 ml ≈ 27,5 g)","grams":27.5,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.81,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"169230","description":"Garlic, raw (3 dientes ≈ 9 g)","grams":9,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"173468","description":"Salt, table (1 cucharadita ≈ 4 g)","grams":4,"per100":{"calories":0,"protein_g":0,"carbs_g":0,"fat_g":0,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":38758}}]},"seo":{"title":"Pollo a la naranja en sartén, fácil | Manual de Cocina","description":"Pollo a la naranja en sartén, con muslos dorados y salsa de naranja, miel y tomillo. Para 4 personas, listo en 55 minutos. Receta paso a paso.","image_variants":["/recetas/pollo-a-la-naranja/portada-1x1.webp","/recetas/pollo-a-la-naranja/portada-4x3.webp","/recetas/pollo-a-la-naranja/portada-16x9.webp"],"faq":[{"q":"¿Qué parte del pollo es mejor para el pollo a la naranja?","a":"Los muslos con piel: se doran bien, se mantienen jugosos y la piel aporta sabor a la salsa."},{"q":"¿Se puede usar jugo de naranja de caja?","a":"Sí, si es 100 % zumo, pero el jugo recién exprimido y la ralladura dan un sabor más fresco."},{"q":"¿Cómo se sabe que el pollo está cocido?","a":"Cuando el centro alcanza 75 °C y los jugos salen claros al pincharlo."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"11fb7630-3ca0-5609-a3c8-76e7251729bc","recipe_group_id":"b6867e1c-874c-4f59-89d2-88de2fe8dc39","language":"de","slug":"orangenhaehnchen","public_path":"/de/orangenhaehnchen","source_url":null,"title":"Orangenhähnchen","excerpt":"Orangenhähnchen aus der Pfanne mit goldbraunen Keulen und einer Sauce aus Orangensaft, Honig und Thymian. Für 4 Personen, fertig in 55 Minuten.","summary":"Für das Orangenhähnchen werden Hähnchenschenkel mit Haut in der Pfanne angebraten und in einer Sauce aus Orangensaft, Orangenschale, Honig, Knoblauch und Thymian gegart. Zuerst werden sie angebraten, damit die Haut knusprig wird, danach garen sie zugedeckt bei niedriger Hitze.\n\nSie garen 15 Minuten zugedeckt und weitere 10 Minuten offen, bis die Sauce eindickt und das Hähnchen überzieht. Serviert wird mit Orangenscheiben. Ergibt 4 Portionen.","category":"Hauptgerichte","difficulty":"Einfach","course":"Hauptgericht","cuisine":"Mediterran","prep_time_minutes":15,"cook_time_minutes":40,"total_time_minutes":55,"servings":4,"keywords":["Orangenhähnchen","Orangenhähnchen Rezept","Hähnchen in Orangensauce","Hähnchenschenkel mit Orange","Orangenhähnchen Pfanne","Hähnchen mit Honig und Orange","pollo a la naranja"],"ingredients":[{"name":"Hähnchenschenkel mit Haut","amount":"1","unit":"kg","group":"Für das Hähnchen"},{"name":"Salz","amount":"1","unit":"Teelöffel","group":"Für das Hähnchen"},{"name":"schwarzer Pfeffer, gemahlen","amount":"0.5","unit":"Teelöffel","group":"Für das Hähnchen"},{"name":"Olivenöl","amount":"30","unit":"ml","group":"Für das Hähnchen"},{"name":"Knoblauchzehen","amount":"3","unit":"","group":"Für das Hähnchen"},{"name":"frisch gepresster Orangensaft (etwa 3 Orangen)","amount":"250","unit":"ml","group":"Für die Sauce"},{"name":"Orangenschale, gerieben","amount":"1","unit":"Esslöffel","group":"Für die Sauce"},{"name":"Honig","amount":"1","unit":"Esslöffel","group":"Für die Sauce"},{"name":"frischer Thymian","amount":"4","unit":"Zweig","group":"Für die Sauce"},{"name":"Orange in Scheiben, zum Servieren","amount":"1","unit":"","group":"Zum Servieren"}],"steps":[{"title":"Zutaten vorbereiten","content":"1 kg Hähnchenschenkel mit Küchenpapier trocken tupfen und mit 1 Teelöffel Salz und ½ Teelöffel Pfeffer würzen. Die Orangen heiß abwaschen, 1 Esslöffel Schale abreiben, 3 Orangen auf 250 ml Saft auspressen, 3 Knoblauchzehen hacken und 1 Orange in Scheiben schneiden.","image_url":"/recetas/pollo-a-la-naranja/paso-01.webp","image_alt":"Orangenhähnchen: Zutaten vorbereiten"},{"title":"Schenkel anbraten","content":"30 ml Öl in einer großen Pfanne bei mittlerer bis hoher Hitze erhitzen. Die Schenkel 6 Minuten mit der Hautseite nach unten anbraten, wenden und weitere 4 Minuten braten. Bei Bedarf in Portionen arbeiten.","image_url":"/recetas/pollo-a-la-naranja/paso-02.webp","image_alt":"Orangenhähnchen: Schenkel anbraten"},{"title":"Knoblauch zugeben","content":"Die Hitze auf mittlere Stufe reduzieren, überschüssiges Fett abgießen und 1 Esslöffel in der Pfanne lassen. Den gehackten Knoblauch zugeben und 1 Minute anbraten, ohne dass er verbrennt.","image_url":"/recetas/pollo-a-la-naranja/paso-03.webp","image_alt":"Orangenhähnchen: Knoblauch zugeben"},{"title":"Saft, Honig und Thymian zugeben","content":"250 ml Orangensaft, 1 Esslöffel Orangenschale, 1 Esslöffel Honig und 4 Zweige Thymian zugeben. Aufkochen und den Bratensatz mit einem Löffel vom Pfannenboden lösen.","image_url":"/recetas/pollo-a-la-naranja/paso-04.webp","image_alt":"Orangenhähnchen: Saft, Honig und Thymian zugeben"},{"title":"Zudecken und garen","content":"Die Pfanne zudecken, die Hitze reduzieren und 15 Minuten garen.","image_url":"/recetas/pollo-a-la-naranja/paso-05.webp","image_alt":"Orangenhähnchen: Zudecken und garen"},{"title":"Aufdecken und begießen","content":"Aufdecken, die Schenkel mit einer Zange wenden und mit der Sauce begießen. Weitere 5 Minuten ohne Deckel garen.","image_url":"/recetas/pollo-a-la-naranja/paso-06.webp","image_alt":"Orangenhähnchen: Aufdecken und begießen"},{"title":"Sauce einkochen","content":"Die Hitze leicht erhöhen und die Sauce 5 Minuten einkochen, bis sie eindickt und die Schenkel überzieht. Das Hähnchen muss im Kern 75 °C erreichen.","image_url":"/recetas/pollo-a-la-naranja/paso-07.webp","image_alt":"Orangenhähnchen: Sauce einkochen"},{"title":"Servieren","content":"Die Schenkel auf eine Platte legen, mit der Sauce begießen und mit den Orangenscheiben und einigen Thymianblättchen servieren.","image_url":"/recetas/pollo-a-la-naranja/paso-08.webp","image_alt":"Orangenhähnchen: Servieren"}],"image_url":"/recetas/pollo-a-la-naranja/portada.webp","gallery":[{"url":"/recetas/pollo-a-la-naranja/portada.webp","alt":"Orangenhähnchen"}],"notes":"Das Hähnchen gut trocken tupfen, damit die Haut bräunt. Schenkel mit Knochen brauchen etwa 10 Minuten länger. Die Sauce wird leichter, wenn Sie überschüssiges Fett vor dem Saft abgießen. Ist die Orange sehr süß, am Ende einige Tropfen Zitronensaft zugeben. Abgedeckt im Kühlschrank bis zu 3 Tage haltbar, bei niedriger Hitze erwärmen.","nutrition":{"calories":662,"protein_g":41.9,"carbs_g":12,"fat_g":48.5,"sodium_mg":591,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 1000 g rohe Hähnchenschenkel mit Haut, 258 g Orangensaft (250 ml), 21 g Honig, 27,5 g Olivenöl, 9 g Knoblauch und 4 g Salz. Pfeffer, Thymian, Orangenschale und Orangenscheiben werden nicht gezählt.","note":"Schätzung pro Portion. Das gesamte Fett und das gesamte Salz werden gezählt, obwohl ein Teil des Fetts in der Pfanne bleibt; der Wert ist daher ungefähr und eher hoch. Bei Schenkeln mit Knochen ist der essbare Anteil geringer."},"seo":{"title":"Orangenhähnchen aus der Pfanne, einfach | Manual de Cocina","description":"Orangenhähnchen aus der Pfanne mit goldbraunen Keulen und Sauce aus Orange, Honig und Thymian. Für 4 Personen, fertig in 55 Minuten.","image_variants":["/recetas/pollo-a-la-naranja/portada-1x1.webp","/recetas/pollo-a-la-naranja/portada-4x3.webp","/recetas/pollo-a-la-naranja/portada-16x9.webp"],"faq":[{"q":"Welches Stück Hähnchen eignet sich am besten?","a":"Hähnchenschenkel mit Haut: Sie bräunen gut, bleiben saftig und die Haut gibt der Sauce Geschmack."},{"q":"Kann man gekauften Orangensaft verwenden?","a":"Ja, wenn es 100 % Saft ist. Frisch gepresster Saft und die Schale schmecken aber frischer."},{"q":"Woran erkennt man, dass das Hähnchen gar ist?","a":"Wenn der Kern 75 °C erreicht hat und beim Einstechen klarer Saft austritt."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"60da9915-d181-571a-a24e-31b4356c69f1","recipe_group_id":"b6867e1c-874c-4f59-89d2-88de2fe8dc39","language":"en","slug":"orange-chicken-thighs","public_path":"/en/orange-chicken-thighs","source_url":null,"title":"Orange Chicken Thighs","excerpt":"Skillet orange chicken thighs, browned and cooked in a sauce of orange juice, honey and thyme. Serves 4, ready in 55 minutes.","summary":"These orange chicken thighs are skin-on thighs browned in a skillet and cooked in a sauce of orange juice, zest, honey, garlic and thyme. They are browned first so the skin turns crisp, then cooked covered over low heat.\n\nThey cook 15 minutes covered and 10 minutes uncovered, until the sauce thickens and coats the chicken. Serve with orange slices. It serves 4.","category":"Main dishes","difficulty":"Easy","course":"Main dish","cuisine":"Mediterranean","prep_time_minutes":15,"cook_time_minutes":40,"total_time_minutes":55,"servings":4,"keywords":["orange chicken thighs","orange chicken recipe","chicken in orange sauce","skillet orange chicken","honey orange chicken","how to make orange chicken","pollo a la naranja"],"ingredients":[{"name":"skin-on chicken thighs","amount":"1","unit":"kg","group":"For the chicken"},{"name":"salt","amount":"1","unit":"teaspoon","group":"For the chicken"},{"name":"ground black pepper","amount":"0.5","unit":"teaspoon","group":"For the chicken"},{"name":"olive oil","amount":"30","unit":"ml","group":"For the chicken"},{"name":"garlic cloves","amount":"3","unit":"","group":"For the chicken"},{"name":"freshly squeezed orange juice (about 3 oranges)","amount":"250","unit":"ml","group":"For the sauce"},{"name":"orange zest","amount":"1","unit":"tablespoon","group":"For the sauce"},{"name":"honey","amount":"1","unit":"tablespoon","group":"For the sauce"},{"name":"fresh thyme","amount":"4","unit":"sprig","group":"For the sauce"},{"name":"orange, sliced, to serve","amount":"1","unit":"","group":"To serve"}],"steps":[{"title":"Prepare the ingredients","content":"Pat 1 kg chicken thighs dry with paper towels and season with 1 teaspoon salt and ½ teaspoon pepper. Wash the oranges well, grate 1 tablespoon zest, squeeze 3 oranges to get 250 ml juice, chop 3 garlic cloves and slice 1 orange.","image_url":"/recetas/pollo-a-la-naranja/paso-01.webp","image_alt":"Orange Chicken Thighs: Prepare the ingredients"},{"title":"Brown the thighs","content":"Heat 30 ml oil in a wide skillet over medium-high heat. Brown the thighs skin side down for 6 minutes, turn them and brown for 4 more minutes. Work in batches if they do not fit.","image_url":"/recetas/pollo-a-la-naranja/paso-02.webp","image_alt":"Orange Chicken Thighs: Brown the thighs"},{"title":"Add the garlic","content":"Lower the heat to medium, pour off the excess fat and leave 1 tablespoon in the pan. Add the chopped garlic and cook for 1 minute without letting it burn.","image_url":"/recetas/pollo-a-la-naranja/paso-03.webp","image_alt":"Orange Chicken Thighs: Add the garlic"},{"title":"Pour in the juice, honey and thyme","content":"Add 250 ml orange juice, 1 tablespoon zest, 1 tablespoon honey and 4 sprigs of thyme. Bring to a boil and scrape the bottom of the pan with a spoon.","image_url":"/recetas/pollo-a-la-naranja/paso-04.webp","image_alt":"Orange Chicken Thighs: Pour in the juice, honey and thyme"},{"title":"Cover and cook","content":"Cover the pan, lower the heat and cook for 15 minutes.","image_url":"/recetas/pollo-a-la-naranja/paso-05.webp","image_alt":"Orange Chicken Thighs: Cover and cook"},{"title":"Uncover and baste","content":"Uncover, turn the thighs with tongs and spoon the sauce over them. Cook 5 more minutes uncovered.","image_url":"/recetas/pollo-a-la-naranja/paso-06.webp","image_alt":"Orange Chicken Thighs: Uncover and baste"},{"title":"Reduce the sauce","content":"Raise the heat a little and reduce the sauce for 5 minutes, until it thickens and coats the thighs. The chicken should reach 75 °C (165 °F) in the center.","image_url":"/recetas/pollo-a-la-naranja/paso-07.webp","image_alt":"Orange Chicken Thighs: Reduce the sauce"},{"title":"Serve","content":"Transfer the thighs to a platter, spoon the sauce over and serve with the orange slices and a few thyme leaves.","image_url":"/recetas/pollo-a-la-naranja/paso-08.webp","image_alt":"Orange Chicken Thighs: Serve"}],"image_url":"/recetas/pollo-a-la-naranja/portada.webp","gallery":[{"url":"/recetas/pollo-a-la-naranja/portada.webp","alt":"Orange Chicken Thighs"}],"notes":"Pat the chicken dry so the skin browns. Bone-in thighs need about 10 more minutes of cooking. The sauce is lighter if you pour off the excess fat before adding the juice. If the oranges are very sweet, add a few drops of lemon juice at the end. Keep covered in the fridge for up to 3 days and reheat over low heat.","nutrition":{"calories":662,"protein_g":41.9,"carbs_g":12,"fat_g":48.5,"sodium_mg":591,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings. It uses 1000 g raw skin-on chicken thighs, 258 g orange juice (250 ml), 21 g honey, 27.5 g olive oil, 9 g garlic and 4 g salt. Pepper, thyme, zest and orange slices are not counted.","note":"Estimate per serving. All the fat and all the salt are counted, although some of the fat stays in the pan, so the value is approximate and somewhat high. With bone-in thighs, the edible portion is smaller."},"seo":{"title":"Skillet Orange Chicken Thighs, Easy | Manual de Cocina","description":"Skillet orange chicken thighs, browned and cooked in an orange, honey and thyme sauce. Serves 4, ready in 55 minutes. Step-by-step recipe.","image_variants":["/recetas/pollo-a-la-naranja/portada-1x1.webp","/recetas/pollo-a-la-naranja/portada-4x3.webp","/recetas/pollo-a-la-naranja/portada-16x9.webp"],"faq":[{"q":"Which cut of chicken is best for orange chicken?","a":"Skin-on thighs: they brown well, stay juicy and the skin adds flavor to the sauce."},{"q":"Can I use store-bought orange juice?","a":"Yes, if it is 100% juice, but freshly squeezed juice and zest give a fresher flavor."},{"q":"How do I know the chicken is cooked?","a":"When the center reaches 75 °C (165 °F) and the juices run clear when pierced."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"be69d94d-90f4-5267-ab89-92ff7172349c","recipe_group_id":"b6867e1c-874c-4f59-89d2-88de2fe8dc39","language":"fr","slug":"poulet-a-lorange","public_path":"/fr/poulet-a-lorange","source_url":null,"title":"Poulet à l'orange","excerpt":"Poulet à l'orange à la poêle, avec des cuisses dorées et une sauce au jus d'orange, au miel et au thym. Pour 4 personnes, prêt en 55 minutes.","summary":"Le poulet à l'orange se prépare avec des cuisses de poulet avec la peau, dorées à la poêle et cuites dans une sauce au jus d'orange, zeste, miel, ail et thym. On les dore d'abord pour que la peau soit croustillante, puis on les cuit à couvert, à feu doux.\n\nElles cuisent 15 minutes à couvert et 10 minutes de plus à découvert, jusqu'à ce que la sauce épaississe et nappe le poulet. On sert avec des rondelles d'orange. Pour 4 portions.","category":"Plats principaux","difficulty":"Facile","course":"Plat principal","cuisine":"Méditerranéenne","prep_time_minutes":15,"cook_time_minutes":40,"total_time_minutes":55,"servings":4,"keywords":["poulet à l'orange","recette de poulet à l'orange","cuisses de poulet à l'orange","poulet sauce orange","poulet à l'orange à la poêle","poulet au miel et à l'orange","pollo a la naranja"],"ingredients":[{"name":"cuisses de poulet avec la peau","amount":"1","unit":"kg","group":"Pour le poulet"},{"name":"sel","amount":"1","unit":"cuillère à café","group":"Pour le poulet"},{"name":"poivre noir moulu","amount":"0.5","unit":"cuillère à café","group":"Pour le poulet"},{"name":"huile d'olive","amount":"30","unit":"ml","group":"Pour le poulet"},{"name":"gousses d'ail","amount":"3","unit":"","group":"Pour le poulet"},{"name":"jus d'orange pressé (environ 3 oranges)","amount":"250","unit":"ml","group":"Pour la sauce"},{"name":"zeste d'orange râpé","amount":"1","unit":"cuillère à soupe","group":"Pour la sauce"},{"name":"miel","amount":"1","unit":"cuillère à soupe","group":"Pour la sauce"},{"name":"thym frais","amount":"4","unit":"brin","group":"Pour la sauce"},{"name":"orange en rondelles, pour servir","amount":"1","unit":"","group":"Pour servir"}],"steps":[{"title":"Préparer les ingrédients","content":"Sécher 1 kg de cuisses de poulet avec du papier absorbant et assaisonner avec 1 cuillère à café de sel et ½ de poivre. Bien laver les oranges, râper 1 cuillère à soupe de zeste, presser 3 oranges pour obtenir 250 ml de jus, hacher 3 gousses d'ail et couper 1 orange en rondelles.","image_url":"/recetas/pollo-a-la-naranja/paso-01.webp","image_alt":"Poulet à l'orange: Préparer les ingrédients"},{"title":"Dorer les cuisses","content":"Chauffer 30 ml d'huile dans une grande poêle à feu moyen-vif. Dorer les cuisses côté peau 6 minutes, les retourner et les dorer 4 minutes de plus. Procéder en plusieurs fois si elles ne tiennent pas.","image_url":"/recetas/pollo-a-la-naranja/paso-02.webp","image_alt":"Poulet à l'orange: Dorer les cuisses"},{"title":"Ajouter l'ail","content":"Baisser à feu moyen, retirer l'excès de graisse en en laissant 1 cuillère à soupe dans la poêle. Ajouter l'ail haché et le faire revenir 1 minute sans le brûler.","image_url":"/recetas/pollo-a-la-naranja/paso-03.webp","image_alt":"Poulet à l'orange: Ajouter l'ail"},{"title":"Verser le jus, le miel et le thym","content":"Ajouter 250 ml de jus d'orange, 1 cuillère à soupe de zeste, 1 cuillère à soupe de miel et 4 brins de thym. Porter à ébullition et gratter le fond de la poêle avec une cuillère.","image_url":"/recetas/pollo-a-la-naranja/paso-04.webp","image_alt":"Poulet à l'orange: Verser le jus, le miel et le thym"},{"title":"Couvrir et cuire","content":"Couvrir la poêle, baisser le feu et cuire 15 minutes.","image_url":"/recetas/pollo-a-la-naranja/paso-05.webp","image_alt":"Poulet à l'orange: Couvrir et cuire"},{"title":"Découvrir et arroser","content":"Découvrir, retourner les cuisses avec des pinces et les arroser de sauce. Cuire 5 minutes de plus à découvert.","image_url":"/recetas/pollo-a-la-naranja/paso-06.webp","image_alt":"Poulet à l'orange: Découvrir et arroser"},{"title":"Réduire la sauce","content":"Augmenter un peu le feu et réduire la sauce 5 minutes, jusqu'à ce qu'elle épaississe et nappe les cuisses. Le poulet doit atteindre 75 °C à cœur.","image_url":"/recetas/pollo-a-la-naranja/paso-07.webp","image_alt":"Poulet à l'orange: Réduire la sauce"},{"title":"Servir","content":"Transférer les cuisses sur un plat, les napper de sauce et servir avec les rondelles d'orange et quelques feuilles de thym.","image_url":"/recetas/pollo-a-la-naranja/paso-08.webp","image_alt":"Poulet à l'orange: Servir"}],"image_url":"/recetas/pollo-a-la-naranja/portada.webp","gallery":[{"url":"/recetas/pollo-a-la-naranja/portada.webp","alt":"Poulet à l'orange"}],"notes":"Bien sécher le poulet pour que la peau dore. Les cuisses avec os demandent environ 10 minutes de cuisson de plus. La sauce est plus légère si l'on retire l'excès de graisse avant d'ajouter le jus. Si les oranges sont très sucrées, ajouter quelques gouttes de citron à la fin. Se conserve couvert au réfrigérateur jusqu'à 3 jours et se réchauffe à feu doux.","nutrition":{"calories":662,"protein_g":41.9,"carbs_g":12,"fat_g":48.5,"sodium_mg":591,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 1000 g de cuisses de poulet crues avec la peau, 258 g de jus d'orange (250 ml), 21 g de miel, 27,5 g d'huile d'olive, 9 g d'ail et 4 g de sel. Le poivre, le thym, le zeste et les rondelles d'orange ne sont pas comptés.","note":"Estimation par portion. Toute la graisse et tout le sel sont comptés, bien qu'une partie de la graisse reste dans la poêle ; la valeur est donc approximative et plutôt haute. Avec des cuisses avec os, la part comestible est plus petite."},"seo":{"title":"Poulet à l'orange à la poêle, facile | Manual de Cocina","description":"Poulet à l'orange à la poêle, cuisses dorées et sauce à l'orange, au miel et au thym. Pour 4 personnes, prêt en 55 minutes. Recette pas à pas.","image_variants":["/recetas/pollo-a-la-naranja/portada-1x1.webp","/recetas/pollo-a-la-naranja/portada-4x3.webp","/recetas/pollo-a-la-naranja/portada-16x9.webp"],"faq":[{"q":"Quel morceau de poulet choisir pour le poulet à l'orange ?","a":"Les cuisses avec la peau : elles dorent bien, restent juteuses et la peau parfume la sauce."},{"q":"Peut-on utiliser du jus d'orange du commerce ?","a":"Oui, s'il est 100 % pur jus, mais le jus pressé et le zeste donnent un goût plus frais."},{"q":"Comment savoir si le poulet est cuit ?","a":"Quand le centre atteint 75 °C et que le jus qui s'écoule est clair à la piqûre."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"52d5430a-0086-5776-9ae1-ba4995ba7858","recipe_group_id":"b6867e1c-874c-4f59-89d2-88de2fe8dc39","language":"it","slug":"pollo-all-arancia","public_path":"/it/pollo-all-arancia","source_url":null,"title":"Pollo all'arancia","excerpt":"Pollo all'arancia in padella, con cosce dorate e una salsa di succo d'arancia, miele e timo. Per 4 persone, pronto in 55 minuti.","summary":"Il pollo all'arancia si prepara con cosce di pollo con la pelle, rosolate in padella e cotte in una salsa di succo d'arancia, scorza, miele, aglio e timo. Si rosolano prima perché la pelle diventi croccante, poi si cuociono coperte a fuoco basso.\n\nCuociono 15 minuti coperte e altri 10 minuti scoperte, finché la salsa si addensa e avvolge il pollo. Si serve con fette d'arancia. Per 4 porzioni.","category":"Secondi piatti","difficulty":"Facile","course":"Secondo piatto","cuisine":"Mediterranea","prep_time_minutes":15,"cook_time_minutes":40,"total_time_minutes":55,"servings":4,"keywords":["pollo all'arancia","ricetta pollo all'arancia","cosce di pollo all'arancia","pollo in salsa d'arancia","pollo all'arancia in padella","pollo al miele e arancia","pollo a la naranja"],"ingredients":[{"name":"cosce di pollo con la pelle","amount":"1","unit":"kg","group":"Per il pollo"},{"name":"sale","amount":"1","unit":"cucchiaino","group":"Per il pollo"},{"name":"pepe nero macinato","amount":"0.5","unit":"cucchiaino","group":"Per il pollo"},{"name":"olio d'oliva","amount":"30","unit":"ml","group":"Per il pollo"},{"name":"spicchi d'aglio","amount":"3","unit":"","group":"Per il pollo"},{"name":"succo d'arancia spremuto (circa 3 arance)","amount":"250","unit":"ml","group":"Per la salsa"},{"name":"scorza d'arancia grattugiata","amount":"1","unit":"cucchiaio","group":"Per la salsa"},{"name":"miele","amount":"1","unit":"cucchiaio","group":"Per la salsa"},{"name":"timo fresco","amount":"4","unit":"rametto","group":"Per la salsa"},{"name":"arancia a fette, per servire","amount":"1","unit":"","group":"Per servire"}],"steps":[{"title":"Prepara gli ingredienti","content":"Asciuga 1 kg di cosce di pollo con carta da cucina e condiscile con 1 cucchiaino di sale e ½ di pepe. Lava bene le arance, gratta 1 cucchiaio di scorza, spremi 3 arance per ottenere 250 ml di succo, trita 3 spicchi d'aglio e affetta 1 arancia.","image_url":"/recetas/pollo-a-la-naranja/paso-01.webp","image_alt":"Pollo all'arancia: Prepara gli ingredienti"},{"title":"Rosola le cosce","content":"Scalda 30 ml di olio in una padella larga a fuoco medio-alto. Rosola le cosce con la pelle verso il basso per 6 minuti, girale e rosolale per altri 4 minuti. Se non ci stanno, procedi a più riprese.","image_url":"/recetas/pollo-a-la-naranja/paso-02.webp","image_alt":"Pollo all'arancia: Rosola le cosce"},{"title":"Aggiungi l'aglio","content":"Abbassa il fuoco a medio, elimina il grasso in eccesso lasciandone 1 cucchiaio in padella. Aggiungi l'aglio tritato e soffriggilo per 1 minuto senza bruciarlo.","image_url":"/recetas/pollo-a-la-naranja/paso-03.webp","image_alt":"Pollo all'arancia: Aggiungi l'aglio"},{"title":"Versa il succo, il miele e il timo","content":"Aggiungi 250 ml di succo d'arancia, 1 cucchiaio di scorza, 1 cucchiaio di miele e 4 rametti di timo. Porta a ebollizione e stacca il fondo della padella con un cucchiaio.","image_url":"/recetas/pollo-a-la-naranja/paso-04.webp","image_alt":"Pollo all'arancia: Versa il succo, il miele e il timo"},{"title":"Copri e cuoci","content":"Copri la padella, abbassa il fuoco e cuoci per 15 minuti.","image_url":"/recetas/pollo-a-la-naranja/paso-05.webp","image_alt":"Pollo all'arancia: Copri e cuoci"},{"title":"Scopri e irrora le cosce","content":"Scopri, gira le cosce con le pinze e irrorale con la salsa. Cuoci altri 5 minuti senza coperchio.","image_url":"/recetas/pollo-a-la-naranja/paso-06.webp","image_alt":"Pollo all'arancia: Scopri e irrora le cosce"},{"title":"Riduci la salsa","content":"Alza leggermente il fuoco e riduci la salsa per 5 minuti, finché si addensa e avvolge le cosce. Il pollo deve raggiungere 75 °C al centro.","image_url":"/recetas/pollo-a-la-naranja/paso-07.webp","image_alt":"Pollo all'arancia: Riduci la salsa"},{"title":"Servi","content":"Trasferisci le cosce su un piatto da portata, irrorale con la salsa e servi con le fette d'arancia e qualche foglia di timo.","image_url":"/recetas/pollo-a-la-naranja/paso-08.webp","image_alt":"Pollo all'arancia: Servi"}],"image_url":"/recetas/pollo-a-la-naranja/portada.webp","gallery":[{"url":"/recetas/pollo-a-la-naranja/portada.webp","alt":"Pollo all'arancia"}],"notes":"Asciuga bene il pollo perché la pelle rosoli. Le cosce con l'osso richiedono circa 10 minuti di cottura in più. La salsa risulta più leggera se elimini il grasso in eccesso prima di aggiungere il succo. Se le arance sono molto dolci, aggiungi qualche goccia di limone alla fine. Si conserva coperto in frigorifero fino a 3 giorni e si riscalda a fuoco basso.","nutrition":{"calories":662,"protein_g":41.9,"carbs_g":12,"fat_g":48.5,"sodium_mg":591,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni. Si usano 1000 g di cosce di pollo crude con la pelle, 258 g di succo d'arancia (250 ml), 21 g di miele, 27,5 g di olio d'oliva, 9 g di aglio e 4 g di sale. Pepe, timo, scorza e fette d'arancia non sono conteggiati.","note":"Stima per porzione. Si conteggiano tutto il grasso e tutto il sale, anche se parte del grasso resta in padella; il valore è quindi approssimativo e piuttosto alto. Con le cosce con l'osso la parte edibile è minore."},"seo":{"title":"Pollo all'arancia in padella, facile | Manual de Cocina","description":"Pollo all'arancia in padella, cosce dorate e salsa di arancia, miele e timo. Per 4 persone, pronto in 55 minuti. Ricetta passo dopo passo.","image_variants":["/recetas/pollo-a-la-naranja/portada-1x1.webp","/recetas/pollo-a-la-naranja/portada-4x3.webp","/recetas/pollo-a-la-naranja/portada-16x9.webp"],"faq":[{"q":"Quale taglio di pollo è migliore per il pollo all'arancia?","a":"Le cosce con la pelle: rosolano bene, restano succose e la pelle dà sapore alla salsa."},{"q":"Posso usare il succo d'arancia confezionato?","a":"Sì, se è 100 % succo, ma il succo spremuto e la scorza danno un sapore più fresco."},{"q":"Come capisco che il pollo è cotto?","a":"Quando il centro raggiunge 75 °C e il succo che esce è limpido se lo punzecchi."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"f0970ac2-daa8-5dd6-9652-6a7d3bbdd8b7","recipe_group_id":"b6867e1c-874c-4f59-89d2-88de2fe8dc39","language":"ja","slug":"オレンジチキン","public_path":"/ja/オレンジチキン","source_url":null,"title":"オレンジチキン","excerpt":"フライパンで作るオレンジチキン。こんがり焼いた鶏もも肉を、オレンジジュースとはちみつ、タイムのソースで煮ます。4人分、55分で完成。","summary":"このオレンジチキンは、皮つきの鶏もも肉をフライパンで焼き、オレンジジュース、オレンジの皮、はちみつ、にんにく、タイムのソースで煮込みます。先に焼いて皮をパリッとさせ、そのあとふたをして弱火で火を通します。\n\nふたをして15分、ふたを外してさらに10分、ソースがとろりとして鶏肉にからむまで煮ます。オレンジの薄切りを添えて食べます。4人分です。","category":"主菜","difficulty":"簡単","course":"主菜","cuisine":"地中海料理","prep_time_minutes":15,"cook_time_minutes":40,"total_time_minutes":55,"servings":4,"keywords":["オレンジチキン","オレンジチキン 作り方","オレンジチキン レシピ","鶏もも肉 オレンジ","オレンジソース チキン","はちみつオレンジチキン","ポージョ・ア・ラ・ナランハ"],"ingredients":[{"name":"皮つき鶏もも肉","amount":"1","unit":"kg","group":"鶏肉用"},{"name":"塩","amount":"1","unit":"小さじ","group":"鶏肉用"},{"name":"黒こしょう（挽いたもの）","amount":"0.5","unit":"小さじ","group":"鶏肉用"},{"name":"オリーブオイル","amount":"30","unit":"ml","group":"鶏肉用"},{"name":"にんにく","amount":"3","unit":"","group":"鶏肉用"},{"name":"搾りたてのオレンジジュース（オレンジ約3個分）","amount":"250","unit":"ml","group":"ソース用"},{"name":"オレンジの皮（すりおろし）","amount":"1","unit":"大さじ","group":"ソース用"},{"name":"はちみつ","amount":"1","unit":"大さじ","group":"ソース用"},{"name":"生タイム","amount":"4","unit":"枝","group":"ソース用"},{"name":"オレンジの薄切り（飾り用）","amount":"1","unit":"","group":"盛り付け用"}],"steps":[{"title":"材料を準備する","content":"皮つき鶏もも肉1kgをキッチンペーパーで水気をふき、塩小さじ1と黒こしょう小さじ1/2をふります。オレンジをよく洗い、皮を大さじ1すりおろし、3個を搾って250mlのジュースにし、にんにく3片をみじん切りにし、オレンジ1個を薄切りにします。","image_url":"/recetas/pollo-a-la-naranja/paso-01.webp","image_alt":"オレンジチキン: 材料を準備する"},{"title":"鶏肉を焼く","content":"大きめのフライパンにオリーブオイル30mlを入れ、中強火で熱します。鶏肉を皮目を下にして6分焼き、裏返してさらに4分焼きます。入らない場合は数回に分けます。","image_url":"/recetas/pollo-a-la-naranja/paso-02.webp","image_alt":"オレンジチキン: 鶏肉を焼く"},{"title":"にんにくを加える","content":"中火に落とし、余分な脂を捨てて大さじ1だけ残します。みじん切りのにんにくを加え、焦がさないように1分炒めます。","image_url":"/recetas/pollo-a-la-naranja/paso-03.webp","image_alt":"オレンジチキン: にんにくを加える"},{"title":"ジュースとはちみつ、タイムを加える","content":"オレンジジュース250ml、すりおろした皮大さじ1、はちみつ大さじ1、タイム4枝を加えます。煮立たせ、スプーンでフライパンの底をこそげます。","image_url":"/recetas/pollo-a-la-naranja/paso-04.webp","image_alt":"オレンジチキン: ジュースとはちみつ、タイムを加える"},{"title":"ふたをして煮る","content":"フライパンにふたをし、火を弱めて15分煮ます。","image_url":"/recetas/pollo-a-la-naranja/paso-05.webp","image_alt":"オレンジチキン: ふたをして煮る"},{"title":"ふたを外してソースをかける","content":"ふたを外し、トングで鶏肉を裏返してソースをかけます。ふたをせずにさらに5分煮ます。","image_url":"/recetas/pollo-a-la-naranja/paso-06.webp","image_alt":"オレンジチキン: ふたを外してソースをかける"},{"title":"ソースを煮詰める","content":"火を少し強め、ソースを5分煮詰めます。とろりとして鶏肉にからめばできあがりです。鶏肉の中心温度は75℃になるようにします。","image_url":"/recetas/pollo-a-la-naranja/paso-07.webp","image_alt":"オレンジチキン: ソースを煮詰める"},{"title":"盛り付ける","content":"鶏肉を皿に盛り、ソースをかけて、オレンジの薄切りとタイムの葉を添えます。","image_url":"/recetas/pollo-a-la-naranja/paso-08.webp","image_alt":"オレンジチキン: 盛り付ける"}],"image_url":"/recetas/pollo-a-la-naranja/portada.webp","gallery":[{"url":"/recetas/pollo-a-la-naranja/portada.webp","alt":"オレンジチキン"}],"notes":"皮がこんがりするよう、鶏肉の水気をしっかりふいてください。骨つきの場合は、加熱時間を約10分長くします。ジュースを入れる前に余分な脂を捨てると、ソースが軽くなります。オレンジがとても甘いときは、最後にレモン汁を数滴加えてください。ふたをして冷蔵庫で3日まで保存でき、弱火で温め直します。","nutrition":{"calories":662,"protein_g":41.9,"carbs_g":12,"fat_g":48.5,"sodium_mg":591,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。生の皮つき鶏もも肉1000g、オレンジジュース258g（250ml）、はちみつ21g、オリーブオイル27.5g、にんにく9g、塩4gを使用しています。こしょう、タイム、オレンジの皮、オレンジの薄切りは計算に含めていません。","note":"1人分の目安です。脂の一部はフライパンに残りますが、脂と塩はすべて計算しているため、概算値でやや高めです。骨つきの場合は、食べられる部分が少なくなります。"},"seo":{"title":"オレンジチキンの作り方｜フライパンで簡単 | Manual de Cocina","description":"フライパンで作るオレンジチキン。こんがり焼いた鶏もも肉をオレンジとはちみつ、タイムのソースで煮ます。4人分、55分で完成。","image_variants":["/recetas/pollo-a-la-naranja/portada-1x1.webp","/recetas/pollo-a-la-naranja/portada-4x3.webp","/recetas/pollo-a-la-naranja/portada-16x9.webp"],"faq":[{"q":"オレンジチキンにはどの部位が向いていますか？","a":"皮つきの鶏もも肉です。こんがり焼けてジューシーに仕上がり、皮の旨みがソースに移ります。"},{"q":"市販のオレンジジュースでも作れますか？","a":"果汁100％のものなら使えますが、搾りたてのジュースと皮のほうが爽やかな風味になります。"},{"q":"鶏肉に火が通ったかどうかはどう分かりますか？","a":"中心温度が75℃になり、刺したときに透明な肉汁が出れば火が通っています。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"199dc154-4121-56ef-ade2-0108dbbd7111","recipe_group_id":"b6867e1c-874c-4f59-89d2-88de2fe8dc39","language":"pt","slug":"frango-com-laranja","public_path":"/pt/frango-com-laranja","source_url":null,"title":"Frango com laranja","excerpt":"Frango com laranja na frigideira, com sobrecoxas douradas e molho de suco de laranja, mel e tomilho. Para 4 pessoas, pronto em 55 minutos.","summary":"O frango com laranja é feito com sobrecoxas de frango com pele, douradas na frigideira e cozidas em um molho de suco de laranja, raspas, mel, alho e tomilho. Elas são douradas primeiro para a pele ficar crocante e depois cozinham tampadas, em fogo baixo.\n\nCozinham 15 minutos tampadas e mais 10 minutos sem tampa, até o molho engrossar e envolver o frango. Servem-se com rodelas de laranja. Rende 4 porções.","category":"Pratos principais","difficulty":"Fácil","course":"Prato principal","cuisine":"Mediterrânea","prep_time_minutes":15,"cook_time_minutes":40,"total_time_minutes":55,"servings":4,"keywords":["frango com laranja","receita de frango com laranja","como fazer frango com laranja","sobrecoxa com laranja","frango ao molho de laranja","frango na frigideira","frango com mel e laranja"],"ingredients":[{"name":"sobrecoxas de frango com pele","amount":"1","unit":"kg","group":"Para o frango"},{"name":"sal","amount":"1","unit":"colher de chá","group":"Para o frango"},{"name":"pimenta-do-reino moída","amount":"0.5","unit":"colher de chá","group":"Para o frango"},{"name":"azeite","amount":"30","unit":"ml","group":"Para o frango"},{"name":"dentes de alho","amount":"3","unit":"","group":"Para o frango"},{"name":"suco de laranja espremido na hora (cerca de 3 laranjas)","amount":"250","unit":"ml","group":"Para o molho"},{"name":"raspas de laranja","amount":"1","unit":"colher de sopa","group":"Para o molho"},{"name":"mel","amount":"1","unit":"colher de sopa","group":"Para o molho"},{"name":"tomilho fresco","amount":"4","unit":"ramo","group":"Para o molho"},{"name":"laranja em rodelas, para servir","amount":"1","unit":"","group":"Para servir"}],"steps":[{"title":"Prepare os ingredientes","content":"Seque 1 kg de sobrecoxas com papel-toalha e tempere com 1 colher de chá de sal e ½ de pimenta. Lave bem as laranjas, rale 1 colher de sopa de casca, esprema 3 laranjas até obter 250 ml de suco, pique 3 dentes de alho e corte 1 laranja em rodelas.","image_url":"/recetas/pollo-a-la-naranja/paso-01.webp","image_alt":"Frango com laranja: Prepare os ingredientes"},{"title":"Doure as sobrecoxas","content":"Aqueça 30 ml de azeite em uma frigideira larga em fogo médio-alto. Doure as sobrecoxas com a pele para baixo por 6 minutos, vire e doure por mais 4 minutos. Faça em etapas se não couberem.","image_url":"/recetas/pollo-a-la-naranja/paso-02.webp","image_alt":"Frango com laranja: Doure as sobrecoxas"},{"title":"Junte o alho","content":"Baixe o fogo para médio, retire o excesso de gordura deixando 1 colher de sopa na frigideira. Junte o alho picado e refogue por 1 minuto, sem deixar queimar.","image_url":"/recetas/pollo-a-la-naranja/paso-03.webp","image_alt":"Frango com laranja: Junte o alho"},{"title":"Despeje o suco, o mel e o tomilho","content":"Junte 250 ml de suco de laranja, 1 colher de sopa de raspas, 1 colher de sopa de mel e 4 ramos de tomilho. Leve à fervura e raspe o fundo da frigideira com uma colher.","image_url":"/recetas/pollo-a-la-naranja/paso-04.webp","image_alt":"Frango com laranja: Despeje o suco, o mel e o tomilho"},{"title":"Tampe e cozinhe","content":"Tampe a frigideira, baixe o fogo e cozinhe por 15 minutos.","image_url":"/recetas/pollo-a-la-naranja/paso-05.webp","image_alt":"Frango com laranja: Tampe e cozinhe"},{"title":"Destampe e regue","content":"Destampe, vire as sobrecoxas com uma pinça e regue com o molho. Cozinhe mais 5 minutos sem tampa.","image_url":"/recetas/pollo-a-la-naranja/paso-06.webp","image_alt":"Frango com laranja: Destampe e regue"},{"title":"Reduza o molho","content":"Aumente um pouco o fogo e reduza o molho por 5 minutos, até engrossar e envolver as sobrecoxas. O frango deve chegar a 75 °C no centro.","image_url":"/recetas/pollo-a-la-naranja/paso-07.webp","image_alt":"Frango com laranja: Reduza o molho"},{"title":"Sirva","content":"Transfira as sobrecoxas para uma travessa, regue com o molho e sirva com as rodelas de laranja e algumas folhas de tomilho.","image_url":"/recetas/pollo-a-la-naranja/paso-08.webp","image_alt":"Frango com laranja: Sirva"}],"image_url":"/recetas/pollo-a-la-naranja/portada.webp","gallery":[{"url":"/recetas/pollo-a-la-naranja/portada.webp","alt":"Frango com laranja"}],"notes":"Seque bem o frango para a pele dourar. Sobrecoxas com osso precisam de cerca de 10 minutos a mais de cozimento. O molho fica mais leve se você retirar o excesso de gordura antes de juntar o suco. Se as laranjas forem muito doces, junte algumas gotas de limão no final. Guarde tampado na geladeira por até 3 dias e reaqueça em fogo baixo.","nutrition":{"calories":662,"protein_g":41.9,"carbs_g":12,"fat_g":48.5,"sodium_mg":591,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usam-se 1000 g de sobrecoxas de frango cruas com pele, 258 g de suco de laranja (250 ml), 21 g de mel, 27,5 g de azeite, 9 g de alho e 4 g de sal. Pimenta, tomilho, raspas e rodelas de laranja não são contados.","note":"Estimativa por porção. Toda a gordura e todo o sal são contados, embora parte da gordura fique na frigideira; por isso o valor é aproximado e um pouco alto. Com sobrecoxas com osso, a porção comestível é menor."},"seo":{"title":"Frango com laranja na frigideira, fácil | Manual de Cocina","description":"Frango com laranja na frigideira, sobrecoxas douradas e molho de laranja, mel e tomilho. Para 4 pessoas, pronto em 55 minutos. Receita passo a passo.","image_variants":["/recetas/pollo-a-la-naranja/portada-1x1.webp","/recetas/pollo-a-la-naranja/portada-4x3.webp","/recetas/pollo-a-la-naranja/portada-16x9.webp"],"faq":[{"q":"Qual corte de frango é melhor para o frango com laranja?","a":"Sobrecoxas com pele: douram bem, ficam suculentas e a pele dá sabor ao molho."},{"q":"Posso usar suco de laranja de caixinha?","a":"Sim, se for 100 % suco, mas o suco espremido na hora e as raspas dão um sabor mais fresco."},{"q":"Como sei que o frango está cozido?","a":"Quando o centro chega a 75 °C e o suco que sai ao espetar é claro."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/pollo-a-la-naranja') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
